func pool(jobs <-chan int, n int, work func(int) int) []int {
    results := make(chan int)
    var wg sync.WaitGroup
    for i := 0; i < n; i++ {
        wg.Add(1)
        go func() {
            defer wg.Done()
            for j := range jobs {
                results <- work(j)
            }
        }()
    }
    go func() { wg.Wait(); close(results) }()
    var out []int
    for r := range results {
        out = append(out, r)
    }
    return out
}

# DFS with colors is the standard approach: a back edge to a GRAY (in-stack)
# node proves a cycle. Plain BFS can't distinguish cross edges from back
# edges; Kahn's algorithm (BFS by in-degree) instead detects a cycle if the
# topological order comes up short.

def has_cycle(adj):
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {u: WHITE for u in adj}
    def dfs(u):
        color[u] = GRAY
        for v in adj.get(u, []):
            if color.get(v, WHITE) == GRAY:
                return True
            if color.get(v, WHITE) == WHITE and dfs(v):
                return True
        color[u] = BLACK
        return False
    return any(color[u] == WHITE and dfs(u) for u in list(adj))

def coin_change(coins, amount):
    INF = amount + 1
    dp = [0] + [INF] * amount
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                dp[a] = min(dp[a], dp[a - c] + 1)
    return dp[amount] if dp[amount] <= amount else -1
# Time O(amount * len(coins)), space O(amount).

