import re

def evaluate(src):
    tokens = re.findall(r'\d+\.?\d*|[()+\-*/]', src)
    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def eat():
        nonlocal pos
        t = tokens[pos]
        pos += 1
        return t

    def expr():
        v = term()
        while peek() in ('+', '-'):
            v = v + term() if eat() == '+' else v - term()
        return v

    def term():
        v = factor()
        while peek() in ('*', '/'):
            v = v * factor() if eat() == '*' else v / factor()
        return v

    def factor():
        if peek() == '(':
            eat()
            v = expr()
            eat()  # ')'
            return v
        if peek() == '-':
            eat()
            return -factor()
        return float(eat())

    return expr()
